"""Check three new linked bodies, retaining every preceding source match."""
import hashlib
from pathlib import Path
HERE = Path(__file__).resolve().parent
prior = HERE.parent / 'codex30_parser/check_link.py'
assert hashlib.sha256(prior.read_bytes()).hexdigest() == 'b36393e4c8ebf219b70545dc81c6a29ea4e4d9c7ab702c3aefa6331361dec67c'
source = prior.read_text().replace('build/codex30_parser', 'build/codex30_instructions')
source = source.replace("old.accepted(TARGET / 'build/codex35_sdk/bind.json')", "old.accepted(TARGET / 'build/codex30_reads/bind.json')")
source = source.replace('len(baseline) == 400', 'len(baseline) == 415')
source = source.replace('    assert len(baseline) == 415', "    assert len(baseline) == 415\n    lookup_rows = json.loads((HERE.parent / 'codex25_dxerr/packet.json').read_text())['clean_rows']\n    lookup_proofs = []\n    for row in lookup_rows:\n        row = dict(row)\n        original_object = ROOT / row['object']\n        replacement_object = RUN / 'libraries' / original_object.name\n        assert sha(replacement_object) == sha(TARGET / 'build/codex30_reads/libraries' / original_object.name)\n        original_raw, rebuilt_raw = original_object.read_bytes(), replacement_object.read_bytes()\n        matcher = lookup.load_matcher()\n        left, right = matcher['parse_coff'](original_raw), matcher['parse_coff'](rebuilt_raw)\n        assert len(left['sections']) == len(right['sections'])\n        for left_section, right_section in zip(left['sections'], right['sections']):\n            assert (left_section['name'], left_section['flags'], left_section['rawsize']) == (right_section['name'], right_section['flags'], right_section['rawsize'])\n            assert original_raw[left_section['rawptr']:left_section['rawptr'] + left_section['rawsize']] == rebuilt_raw[right_section['rawptr']:right_section['rawptr'] + right_section['rawsize']]\n            left_symbols = {s['idx']: s for s in left['symbols']}\n            right_symbols = {s['idx']: s for s in right['symbols']}\n            def normalized_relocations(section, symbols):\n                return [(r['vaddr'], r['type'], symbols[r['sym']]['name'], symbols[r['sym']]['value'], symbols[r['sym']]['sec']) for r in section['relocs']]\n            assert normalized_relocations(left_section, left_symbols) == normalized_relocations(right_section, right_symbols)\n        row['object'] = str(replacement_object.relative_to(ROOT))\n        lookup_proofs.append(old.check_linked_lookup(row))\n    assert baseline['_DXGetErrorString9W@4'] == ('0x100de367', 72405)\n    baseline['_DXGetErrorString9W@4'] = ('0x100de367', 48462)")
source = source.replace("if row['name'].startswith('_DXGetErrorDescription9'):", "if row['name'].startswith('_DXGetErrorDescription9') or row['name'] == '_DXGetErrorString9W@4':")
source = source.replace("    helpers = json.loads", "    for earlier_name in ('codex30_parser', 'codex30_reads'):\n        earlier = json.loads((HERE.parent / earlier_name / 'clean_packet.json').read_text())\n        parsers['rows'] += earlier['rows']\n        parsers['files'].update(earlier['files'])\n        parsers['verified_instruction_bytes'] += earlier['verified_instruction_bytes']\n    helpers = json.loads")
source = source.replace("parsers['verified_instruction_bytes'] == 6082", "parsers['verified_instruction_bytes'] == 7170")
source = source.replace("'baseline_source_matches': 400", "'baseline_source_matches': 415")
source = source.replace('all 400 previous', 'all 415 previous')
source = source.replace("for left_section, right_section in zip(left['sections'], right['sections']):\n            assert", "for left_section, right_section in zip(left['sections'], right['sections']):\n            assert left_section['name'] == right_section['name']\n            if left_section['name'].startswith('.debug$'):\n                continue  # Source-path debug metadata, never executable code/data.\n            assert")
source = source.replace("'linked_parsers': linked_parsers,", "'linked_parsers': linked_parsers, 'linked_lookup_proofs': lookup_proofs, 'baseline_extent_correction': {'symbol': '_DXGetErrorString9W@4', 'old_section_bytes': 72405, 'instruction_bytes': 48462, 'full_section_still_verified': True},")
source = source.replace("    baseline['_DXGetErrorString9W@4'] = ('0x100de367', 48462)", "    baseline['_DXGetErrorString9W@4'] = ('0x100de367', 48462)\n    assert baseline['_DXGetErrorString9A@4'] == ('0x100cc81b', 72524)\n    baseline['_DXGetErrorString9A@4'] = ('0x100cc81b', 48427)")
source = source.replace("        if row['name'].startswith('_DXGetErrorDescription9')", "        if row['name'] == '_DXGetErrorString9A@4':\n            proof, = [p for p in lookup_rows if p['symbol'] == row['name']]\n            assert proof['address'] in row['hits']\n            row['hits'], row['size'] = [proof['address']], proof['code_bytes']\n        if row['name'].startswith('_DXGetErrorDescription9')")
source = source.replace("'linked_lookup_proofs': lookup_proofs,", "'linked_lookup_proofs': lookup_proofs, 'additional_baseline_extent_corrections': [{'symbol': '_DXGetErrorString9A@4', 'old_section_bytes': 72524, 'instruction_bytes': 48427, 'full_section_still_verified': True}],")
source = source.replace("str(binder), str(dll)", "str(HERE / 'sdk_binding.py'), str(dll)")
source = source.replace("compare, binder, *snapshot.values()", "compare, binder, HERE / 'sdk_binding.py', *snapshot.values()")
exec(compile(source, str(prior), 'exec'), {'__file__': str(HERE / 'check_link.py'), '__name__': '__main__'})
